<script setup lang="ts">
import {fontSize} from '../font-size';
import {computed} from 'vue';import {Refresh} from '@element-plus/icons-vue';import PageHeading from '../components/PageHeading.vue';import Chart from '../components/Chart.vue';import {useData} from '../store';import {accountName,remaining,risk,date} from '../domain';import {theme} from '../theme';
const data=useData();const metrics=computed(()=>[{label:'在线设备',value:data.active.length,unit:`/ ${data.snapshot?.machines.length??0} 台`},{label:'在用账号',value:new Set(data.active.map(m=>m.account_id).filter(Boolean)).size,unit:'个'},{label:'额度预警',value:data.accounts.filter(risk).length??0,unit:'个'},{label:'设备在线率',value:data.snapshot?.machines.length?Math.round(data.active.length/data.snapshot.machines.length*100):'—',unit:'%'}]);
const bars=computed(()=>{const list=(data.accounts||[]).filter(a=>remaining(a)!==null);return {aria:{enabled:true},grid:{left:8,right:45,top:8,bottom:8,containLabel:true},tooltip:{trigger:'axis',renderMode:'richText'},xAxis:{type:'value',max:100,axisLabel:{color:'#7991a7',formatter:'{value}%'},splitLine:{lineStyle:{color:theme.value==='light'?'#e3edf5':'#214354'}}},yAxis:{type:'category',data:list.map(accountName),axisLabel:{color:theme.value==='light'?'#365675':'#bad9e9',width:140,overflow:'truncate'},axisLine:{show:false},axisTick:{show:false}},series:[{type:'bar',data:list.map(a=>({value:remaining(a),itemStyle:{color:(remaining(a)??100)<20?'#d99a45':'#26a4b9'}})),barWidth:12,label:{show:true,position:'right',formatter:'{c}%',color:'#7991a7'}}]};});
const graph=computed(()=>{const nodes=[{id:'server',name:'额度服务',value:data.active.length,symbolSize:54,itemStyle:{color:'#149db8'}}];const links:{source:string;target:string}[]=[];for(const m of data.snapshot?.machines||[]){nodes.push({id:String(m.machine_id),name:m.label,value:data.active.some(x=>x.machine_id===m.machine_id)?1:0,symbolSize:30,itemStyle:{color:data.active.some(x=>x.machine_id===m.machine_id)?'#38b993':'#8295a7'}});links.push({source:'server',target:String(m.machine_id)});}return {aria:{enabled:true},tooltip:{renderMode:'richText'},series:[{type:'graph',layout:'circular',roam:false,data:nodes,links,label:{show:true,position:'bottom',color:theme.value==='light'?'#365675':'#a8ccdd',fontSize:10*fontSize.value/100},lineStyle:{color:'#539eb1',type:'dashed',opacity:.6},emphasis:{focus:'adjacency'}}]};});
</script><template><PageHeading title="额度运行态势" note="按真实账号聚合额度，按实际设备周期判断在线。" eyebrow="LIVE OPERATIONS CENTER"><el-button :icon="Refresh" :loading="data.loading" @click="data.refresh">刷新数据</el-button></PageHeading><template v-if="data.snapshot"><div class="metrics"><div v-for="m in metrics" :key="m.label" class="metric"><div class="metric-top">{{m.label}}</div><div class="metric-value">{{m.value}}<small>{{m.unit}}</small></div><div class="metric-bottom">当前服务端快照</div></div></div><div class="dashboard-grid"><section class="panel trend-panel"><div class="panel-head"><span class="panel-title">账号剩余容量</span><el-tag size="small">最新读数 · 非历史趋势</el-tag></div><div class="panel-body"><Chart v-if="data.accounts.some(a=>remaining(a)!==null)" :option="bars" label="各账号主窗口剩余额度百分比"/><el-empty v-else description="尚无可用额度读数"/><p class="small-label">当前接口未提供历史序列，不绘制推测的历史曲线。</p></div></section><section class="panel"><div class="panel-head"><span class="panel-title">设备连接拓扑</span></div><Chart v-if="data.snapshot.machines.length" :option="graph" label="设备在线状态拓扑，详情见设备监控"/><el-empty v-else description="暂无接入设备"/></section><section class="panel"><div class="panel-head"><span class="panel-title">账号概况</span><RouterLink to="/accounts">查看全部</RouterLink></div><div class="panel-body"><div v-for="a in data.accounts" :key="a.key" class="account-mini"><div class="flex-between"><span>{{accountName(a)}}</span><span class="cyan mono">{{remaining(a)===null?'未知':remaining(a)+'%'}}</span></div><div class="mini-footer">在线 {{a.active_machine_count}} 台 · {{a.plan_type||'套餐未知'}}</div></div><el-empty v-if="!data.accounts.length" description="暂无账号"/></div></section><section class="panel"><div class="panel-head"><span class="panel-title">在线设备</span><RouterLink to="/devices">查看详情</RouterLink></div><div class="panel-body"><div v-for="m in data.active" :key="m.machine_id" class="device-line"><span class="status-pill">在线</span><div class="device-info"><b>{{m.label}}</b><small>{{accountName(m)}}</small></div></div><el-empty v-if="!data.active.length" description="当前没有在线设备"/></div></section><section class="panel"><div class="panel-head"><span class="panel-title">最近成功上报</span></div><div class="panel-body"><div v-for="m in [...data.snapshot.machines].filter(m=>m.last_ok_at).sort((a,b)=>(b.last_ok_at??0)-(a.last_ok_at??0)).slice(0,4)" :key="m.machine_id" class="event"><time>{{date(m.last_ok_at)}}</time><p>{{m.label}}<small>{{m.source==='app_server'?'app-server核验来源':'历史或未知来源，不能确认当前身份'}}</small></p></div><p class="small-label">展示最新记录，不作为完整审计日志。</p></div></section></div></template><el-empty v-else description="等待可用服务数据"/></template>
